package cn.haiduo;
import java.util.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.context.support.GenericApplicationContext;
import org.springframework.web.server.ResponseStatusException;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.flywaydb.core.Flyway;
import cn.haiduo.inventory.InventoryService;
import cn.haiduo.audit.Audit;

@org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable(named="RUN_DATABASE_TESTS",matches="true")
class WorkflowContainerTest {
 static PostgreSQLContainer pg;static JdbcTemplate db;static TransactionTemplate tx;
 UUID tenant,sku,order,warehouse;MockHttpSession session;GenericApplicationContext context;OperationsController ops;ProductController products;BusinessEdits edits;WorkflowController workflows;MemberController members;SkuApprovals grades;FulfillmentController fulfillment;
 @BeforeAll static void start(){pg=new PostgreSQLContainer("postgres:17.6").withDatabaseName("haiduo").withUsername("haiduo").withPassword("test-password");pg.start();var ds=new DriverManagerDataSource(pg.getJdbcUrl(),pg.getUsername(),pg.getPassword());Flyway.configure().dataSource(ds).load().migrate();db=new JdbcTemplate(ds);tx=new TransactionTemplate(new DataSourceTransactionManager(ds));}
 @AfterAll static void stop(){if(pg!=null)pg.stop();}
 @BeforeEach void setup(){tenant=UUID.randomUUID();warehouse=UUID.fromString("00000000-0000-0000-0000-000000000001");sku=UUID.randomUUID();db.update("insert into tenant values(?,'workflow')",tenant);db.update("insert into warehouse values(?,?,'default')",tenant,warehouse);for(String user:List.of("owner","peer","intern","supervisor","warehouse")){db.update("insert into app_user(username,password_hash) values(?,'unused') on conflict do nothing",user);db.update("insert into membership values(?,?,?)",user,tenant,Set.of("owner","peer").contains(user)?"ADMIN":user.equals("warehouse")?"WAREHOUSE":"OPERATIONS");db.update("insert into member_grade values(?,?,?)",tenant,user,user.equals("intern")||user.equals("warehouse")?1:3);}var sessions=new SessionController(db);var inventory=new InventoryService(db);ops=new OperationsController(db,sessions,inventory);products=new ProductController(db,sessions);fulfillment=new FulfillmentController(db,ops,inventory);edits=new BusinessEdits(db,ops);members=new MemberController(db,ops,new Audit(db));grades=new SkuApprovals(db,ops);context=new GenericApplicationContext();context.registerBean(ProductController.class,()->products);context.registerBean(OperationsController.class,()->ops);context.registerBean(FulfillmentController.class,()->fulfillment);context.registerBean(MemberController.class,()->members);context.registerBean(SkuApprovals.class,()->grades);context.registerBean(BusinessEdits.class,()->edits);context.refresh();workflows=new WorkflowController(db,ops,context);session=new MockHttpSession();session.setAttribute("activeTenant",tenant.toString());tx.executeWithoutResult(s->products.create(new ProductController.CreateProduct("A","test","200"),()->"owner",session));sku=db.queryForObject("select id from sku where tenant_id=?",UUID.class,tenant);db.update("update inventory set on_hand=100 where tenant_id=?",tenant);db.update("insert into store(id,tenant_id,name,platform,connection_status) values(?,?,'mock','MOCK','MOCK')",UUID.randomUUID(),tenant);tx.executeWithoutResult(s->ops.importCsv(new OperationsController.Csv("store,order_no,sku,quantity,net,currency,rate\nmock,ONE,A,2,100,USD,7.2",warehouse,null,null),()->"owner",session));order=db.queryForObject("select id from sales_order where tenant_id=?",UUID.class,tenant);}
 @AfterEach void close(){context.close();}
 Map<?,?> decide(UUID id,String action,String actor){return (Map<?,?>)tx.execute(s->workflows.decide(id,new WorkflowController.Decision(action,"review"),()->actor,session));}
 UUID id(Object result){return UUID.fromString(((Map<?,?>)result).get("id").toString());}
 int stock(){return db.queryForObject("select on_hand from inventory where tenant_id=? and sku_id=?",Integer.class,tenant,sku);}
 BusinessEdits.Edit edit(String kind,UUID target,int quantity,int counted,String code,Boolean archived,long version){return new BusinessEdits.Edit(kind,target,version,"edited",code,archived,quantity,counted,warehouse,"test reason",UUID.randomUUID(),"MOCK","NEW-TRACK",List.of(new BusinessEdits.Line(sku,quantity)),stock(),0);}
 Object save(BusinessEdits.Edit r,String actor){return tx.execute(s->edits.save(r,()->actor,session));}
 @Test void ordinaryProductCreationAndImportRequireApproval(){var input=new ProductController.CreateProduct("B","new","10");UUID request=id(tx.execute(s->products.create(input,()->"intern",session)));assertEquals(1,db.queryForObject("select count(*) from sku where tenant_id=?",Integer.class,tenant));assertEquals(403,assertThrows(ResponseStatusException.class,()->decide(request,"approve","intern")).getStatusCode().value());for(int i=0;i<10;i++)decide(request,"approve","supervisor");assertEquals(2,db.queryForObject("select count(*) from sku where tenant_id=?",Integer.class,tenant));var csv=new OperationsController.Csv("store,order_no,sku,quantity,net,currency,rate\nmock,TWO,B,1,10,USD,7.2",warehouse,UUID.randomUUID(),null);UUID imported=id(tx.execute(s->ops.importCsv(csv,()->"intern",session)));assertEquals(1,db.queryForObject("select count(*) from sales_order where tenant_id=?",Integer.class,tenant));decide(imported,"approve","supervisor");assertEquals(2,db.queryForObject("select count(*) from sales_order where tenant_id=?",Integer.class,tenant));}
 @Test void reserveAndShipCannotBypassAndVersionBecomesStale(){UUID pending=id(tx.execute(s->ops.transition(order,"reserve",new OperationsController.TransitionRequest(0L),()->"intern",session)));assertEquals(0,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));java.util.stream.IntStream.range(0,10).parallel().forEach(i->decide(pending,"approve","supervisor"));assertEquals(2,db.queryForObject("select reserved from inventory where tenant_id=?",Integer.class,tenant));UUID ship=id(tx.execute(s->fulfillment.ship(order,new FulfillmentController.Ship("MOCK","TRACK"),()->"warehouse",session)));assertEquals(100,stock());decide(ship,"approve","owner");assertEquals(98,stock());UUID another=UUID.randomUUID();db.update("insert into sales_order(id,tenant_id,store,external_id,net,rate,currency,rate_source,rate_at,warehouse_id) values(?,?,'mock','STALE',1,1,'CNY','test',now(),?)",another,tenant,warehouse);UUID cancel=id(tx.execute(s->ops.transition(another,"cancel",null,()->"intern",session)));db.update("update sales_order set inventory_revision=1 where id=?",another);assertEquals("STALE",decide(cancel,"approve","supervisor").get("status"));}
 @Test void privilegeChangesNeedAnotherAdministratorAndRejectStaleTarget(){UUID promotion=id(tx.execute(s->grades.grade(new SkuApprovals.Grade("intern",3),()->"owner",session)));assertEquals(1,BusinessWorkflows.grade(db,tenant,"intern"));assertThrows(ResponseStatusException.class,()->decide(promotion,"approve","owner"));assertThrows(ResponseStatusException.class,()->decide(promotion,"approve","supervisor"));decide(promotion,"approve","peer");assertEquals(3,BusinessWorkflows.grade(db,tenant,"intern"));UUID role=id(tx.execute(s->members.change(new MemberController.Change("intern","ADMIN"),()->"owner",session)));assertEquals("OPERATIONS",BusinessWorkflows.role(db,tenant,"intern"));db.update("update member_grade set grade=2 where tenant_id=? and username='intern'",tenant);assertEquals("STALE",decide(role,"approve","peer").get("status"));}
 @Test void createdAdministratorStartsWithoutAdministratorRights(){UUID request=id(tx.execute(s->members.create(new MemberController.Create("new-admin-"+tenant,"Long-Test-Password!","ADMIN"),()->"owner",session)));String user="new-admin-"+tenant;assertEquals("OPERATIONS",BusinessWorkflows.role(db,tenant,user));decide(request,"approve","peer");assertEquals("ADMIN",BusinessWorkflows.role(db,tenant,user));}
 @Test void archiveAndAliasKeepHistoryAndBlockNewBusiness(){UUID archive=id(save(edit("PRODUCT_ARCHIVE",sku,1,0,null,true,0),"owner"));decide(archive,"approve","peer");assertThrows(ResponseStatusException.class,()->tx.execute(s->ops.importCsv(new OperationsController.Csv("store,order_no,sku,quantity,net,currency,rate\nmock,BLOCK,A,1,1,CNY,1",warehouse,null,null),()->"owner",session)));UUID restore=id(save(edit("PRODUCT_ARCHIVE",sku,1,0,null,false,1),"owner"));decide(restore,"approve","peer");UUID rename=id(save(edit("SKU_CODE",sku,1,0,"NEW-A",null,0),"owner"));decide(rename,"approve","peer");assertEquals("NEW-A",db.queryForObject("select code from sku where id=?",String.class,sku));var input=new OperationsController.Csv("store,order_no,sku,quantity,net,currency,rate\nmock,ALIAS,A,1,1,CNY,1",warehouse,null,null);tx.executeWithoutResult(s->ops.importCsv(input,()->"owner",session));assertEquals(2,db.queryForObject("select count(*) from sales_order where tenant_id=?",Integer.class,tenant));assertThrows(ResponseStatusException.class,()->tx.execute(s->products.create(new ProductController.CreateProduct("A","collision","1"),()->"owner",session)));}
 @Test void physicalCountHasSnapshotAndCannotFallBelowReserved(){UUID count=id(save(edit("STOCK_COUNT",sku,1,90,null,null,0),"owner"));db.update("update inventory set reserved=1 where tenant_id=?",tenant);assertEquals("STALE",decide(count,"approve","peer").get("status"));assertEquals(100,stock());db.update("update inventory set reserved=0 where tenant_id=?",tenant);UUID next=id(save(edit("STOCK_COUNT",sku,1,90,null,null,0),"owner"));decide(next,"approve","peer");assertEquals(90,stock());assertEquals(-10,db.queryForObject("select quantity from business_adjustment where tenant_id=?",Integer.class,tenant));}
 @Test void partialReversalAndReturnNeverExceedOriginalQuantity(){UUID receipt=UUID.randomUUID();db.update("insert into stock_receipt(tenant_id,request_key,sku_id,quantity,warehouse_id) values(?,?,?,10,?)",tenant,receipt,sku,warehouse);var part=edit("RECEIPT_PARTIAL",receipt,4,0,null,null,0);UUID request=id(save(part,"owner"));for(int i=0;i<10;i++)decide(request,"approve","peer");assertEquals(96,stock());UUID excess=id(save(edit("RECEIPT_PARTIAL",receipt,7,0,null,null,0),"owner"));assertThrows(ResponseStatusException.class,()->decide(excess,"approve","peer"));assertEquals(96,stock());tx.executeWithoutResult(s->{ops.transition(order,"reserve",new OperationsController.TransitionRequest(0L),()->"owner",session);fulfillment.ship(order,new FulfillmentController.Ship("MOCK","TRACK"),()->"owner",session);});UUID returned=id(save(edit("RETURN_RECEIVE",order,1,0,null,null,0),"owner"));decide(returned,"approve","peer");assertEquals(95,stock());UUID tooMuch=id(save(edit("RETURN_RECEIVE",order,2,0,null,null,0),"owner"));assertThrows(ResponseStatusException.class,()->decide(tooMuch,"approve","peer"));assertEquals(95,stock());}
 @Test void csvOrderEditingAndCopyPreserveExistingCostSnapshot(){db.update("update sku set cost=220 where id=?",sku);var change=edit("ORDER_EDIT",order,3,0,null,null,0);save(change,"owner");assertEquals("200.0000",db.queryForObject("select unit_cost_cny::text from order_item where order_id=?",String.class,order));assertEquals(3,db.queryForObject("select quantity from order_item where order_id=?",Integer.class,order));tx.executeWithoutResult(s->ops.transition(order,"cancel",null,()->"owner",session));save(edit("ORDER_COPY",order,1,0,"COPY",null,0),"owner");assertEquals("CANCELLED",db.queryForObject("select status from sales_order where id=?",String.class,order));assertEquals(2,db.queryForObject("select count(*) from sales_order where tenant_id=?",Integer.class,tenant));}
 @Test void rejectedExpiredRevokedAndForeignRequestsCannotExecute(){UUID request=id(tx.execute(s->products.create(new ProductController.CreateProduct("B","test","1"),()->"intern",session)));db.update("update membership set role='WAREHOUSE' where tenant_id=? and username='intern'",tenant);assertThrows(ResponseStatusException.class,()->decide(request,"approve","supervisor"));assertEquals("REJECTED",decide(request,"reject","owner").get("status"));UUID other=UUID.randomUUID();db.update("insert into tenant values(?,'other')",other);db.update("insert into membership values('peer',?,'ADMIN')",other);session.setAttribute("activeTenant",other.toString());assertEquals(404,assertThrows(ResponseStatusException.class,()->decide(request,"approve","peer")).getStatusCode().value());}
 @Test void shipmentEditsUseIndependentOptimisticVersion(){tx.executeWithoutResult(s->{ops.transition(order,"reserve",new OperationsController.TransitionRequest(0L),()->"owner",session);fulfillment.ship(order,new FulfillmentController.Ship("MOCK","ORIGINAL"),()->"owner",session);});UUID shipment=db.queryForObject("select id from shipment where tenant_id=?",UUID.class,tenant);save(edit("SHIPMENT_EDIT",shipment,1,0,null,null,0),"owner");assertEquals("NEW-TRACK",db.queryForObject("select tracking_number from shipment where id=?",String.class,shipment));assertEquals(409,assertThrows(ResponseStatusException.class,()->save(edit("SHIPMENT_EDIT",shipment,1,0,null,null,0),"owner")).getStatusCode().value());assertEquals(1,db.queryForObject("select count(*) from business_history where tenant_id=? and kind='SHIPMENT_EDIT'",Integer.class,tenant));assertEquals(98,stock());}
 @Test void withdrawnAndExpiredRequestsCanBeResubmittedIdempotently(){UUID request=id(tx.execute(s->products.create(new ProductController.CreateProduct("B","test","1"),()->"intern",session)));decide(request,"withdraw","intern");UUID fresh=id(tx.execute(s->workflows.resubmit(request,()->"intern",session)));assertNotEquals(request,fresh);for(int i=0;i<10;i++)assertEquals(fresh,id(tx.execute(s->workflows.resubmit(request,()->"intern",session))));db.update("update business_request set expires_at=now()-interval '1 second' where id=?",fresh);assertEquals("EXPIRED",decide(fresh,"approve","supervisor").get("status"));assertEquals(1,db.queryForObject("select count(*) from sku where tenant_id=?",Integer.class,tenant));UUID next=id(tx.execute(s->workflows.resubmit(fresh,()->"intern",session)));decide(next,"approve","supervisor");assertEquals(2,db.queryForObject("select count(*) from sku where tenant_id=?",Integer.class,tenant));}
 @Test void countCannotReduceBelowReservationsAndFailureHasNoAuditEffect(){db.update("update inventory set reserved=5 where tenant_id=?",tenant);var input=new BusinessEdits.Edit("STOCK_COUNT",sku,0,null,null,null,null,4,warehouse,"physical count",UUID.randomUUID(),null,null,null,100,5);UUID request=id(save(input,"owner"));int before=db.queryForObject("select count(*) from outbox_event where tenant_id=?",Integer.class,tenant);assertEquals(409,assertThrows(ResponseStatusException.class,()->decide(request,"approve","peer")).getStatusCode().value());assertEquals(before,db.queryForObject("select count(*) from outbox_event where tenant_id=?",Integer.class,tenant));assertEquals(100,stock());assertEquals(0,db.queryForObject("select count(*) from business_adjustment where tenant_id=?",Integer.class,tenant));}
}
